WITH ranked AS (SELECT * FROM device_readings QUALIFY ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY pressure DESC NULLS LAST, id) = 1), ranked_device_readings AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY device_code ORDER BY humidity DESC) AS rn FROM ranked) x WHERE rn = 1), ranked_device_readings_2 AS (SELECT id, device_code, reading_ts, humidity, firmware, rn FROM ranked_device_readings QUALIFY ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY humidity DESC NULLS FIRST, id) = 1), with_windows AS (SELECT *, MAX(humidity) OVER (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS humidity_max_1h, ROUND(humidity / SUM(humidity) OVER (PARTITION BY device_code), 4) AS humidity_share, AVG(humidity) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS humidity_avg_1h, AVG(humidity) OVER w_part AS humidity_avg_15m, PERCENT_RANK() OVER (ORDER BY humidity DESC) AS humidity_percent_rank FROM ranked_device_readings_2 WINDOW w_part AS (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW)), flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM with_windows), sessions_device_readings AS (SELECT id, device_code, reading_ts, humidity_max_1h, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged), enriched AS (SELECT *, FIRST_VALUE(humidity_max_1h) IGNORE NULLS OVER w_grp AS first_known_humidity_max_1h, LEAD(humidity_max_1h, 1) OVER (PARTITION BY device_code ORDER BY humidity_max_1h, id) AS next_humidity_max_1h, AVG(session_id) OVER (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS session_id_avg_2h, ROUND(humidity_max_1h / SUM(humidity_max_1h) OVER (PARTITION BY device_code), 4) AS humidity_max_1h_share, SUM(humidity_max_1h) OVER (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS humidity_max_1h_sum_30m FROM sessions_device_readings WINDOW w_grp AS (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), metrics AS (SELECT id, humidity_max_1h_share, humidity_max_1h_sum_30m, SUM(humidity_max_1h) OVER (PARTITION BY device_code ORDER BY next_humidity_max_1h, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_humidity_max_1h, FIRST_VALUE(humidity_max_1h_share) IGNORE NULLS OVER (PARTITION BY DATE_TRUNC('WEEK', reading_ts), device_code ORDER BY session_id_avg_2h, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_humidity_max_1h_share, AVG(humidity_max_1h) OVER (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS humidity_max_1h_avg_2h, NTILE(4) OVER (ORDER BY humidity_max_1h DESC, id) AS humidity_max_1h_bucket FROM enriched WHERE first_known_humidity_max_1h >= 41) SELECT id, humidity_max_1h_share, humidity_max_1h_sum_30m, running_humidity_max_1h FROM metrics ORDER BY id DESC NULLS LAST, humidity_max_1h_sum_30m
